@Composable private fun BackendNetwork(modifier:Modifier){val transition=rememberInfiniteTransition(label="backend-network");val phase by transition.animateFloat(0f,1f,infiniteRepeatable(tween(5200,easing=LinearEasing)),label="packet");Canvas(modifier){val c=Offset(size.width/2,size.height/2);val radius=min(size.width,size.height)*.39f;val pts=(0 until 8).map{i->val a=(-PI/2+i*2*PI/8).toFloat();Offset(c.x+cos(a.toDouble()).toFloat()*radius,c.y+sin(a.toDouble()).toFloat()*radius)};pts.forEachIndexed{i,p->drawLine(Color.White.copy(alpha=.10f),c,p,1.5f); val t=(phase+i*.113f)%1f;val q=Offset(c.x+(p.x-c.x)*t,c.y+(p.y-c.y)*t);for(k in 0 until 7){val tt=(t-k*.022f).coerceIn(0f,1f);val trail=Offset(c.x+(p.x-c.x)*tt,c.y+(p.y-c.y)*tt);drawCircle(BackendViolet.copy(alpha=(1-k/7f)*.28f),7f-k*.7f,trail)};drawCircle(Color.White,4f,q)};drawCircle(BackendPurple.copy(alpha=.17f),72f,c);drawCircle(Color.White.copy(alpha=.08f),72f,c,style=Stroke(1f));drawCircle(Color.White,7f,c);pts.forEach{p->drawCircle(Color.White.copy(alpha=.11f),25f,p);drawCircle(BackendViolet,5f,p)}}}
